 WHERE existing_file.source_code=d.source_code
 AND (JSON_UNQUOTE(JSON_EXTRACT(existing_row.data_json,'$.metric_code'))=m.metric_code
 OR CAST(JSON_UNQUOTE(JSON_EXTRACT(existing_row.data_json,'$.metric_id')) AS UNSIGNED)=m.id));

