INSERT INTO metric_realtime(metric_id,metric_value,data_time,is_exceed,exceed_count,status,create_time,update_time)
SELECT v.metric_id,v.metric_value,v.data_time,
 CASE WHEN cfg.alarm_status=1 AND cfg.alarm_threshold IS NOT NULL AND
   ((cfg.alarm_condition='>' AND v.metric_value>cfg.alarm_threshold) OR (cfg.alarm_condition='>=' AND v.metric_value>=cfg.alarm_threshold)
   OR (cfg.alarm_condition='<' AND v.metric_value<cfg.alarm_threshold) OR (cfg.alarm_condition='<=' AND v.metric_value<=cfg.alarm_threshold)
   OR (cfg.alarm_condition IN ('=','==') AND v.metric_value=cfg.alarm_threshold)) THEN 1 ELSE 0 END,
 0,CASE WHEN cfg.alarm_threshold IS NULL OR cfg.alarm_condition IS NULL OR cfg.alarm_condition NOT IN ('>','>=','<','<=','=','==') THEN '待配置' WHEN COALESCE(cfg.alarm_status,0)<>1 THEN '告警停用'
 WHEN ((cfg.alarm_condition='>' AND v.metric_value>cfg.alarm_threshold) OR (cfg.alarm_condition='>=' AND v.metric_value>=cfg.alarm_threshold)
   OR (cfg.alarm_condition='<' AND v.metric_value<cfg.alarm_threshold) OR (cfg.alarm_condition='<=' AND v.metric_value<=cfg.alarm_threshold)
   OR (cfg.alarm_condition IN ('=','==') AND v.metric_value=cfg.alarm_threshold)) THEN '告警' ELSE '正常' END,NOW(),NOW()
FROM (
 SELECT observations.*,ROW_NUMBER() OVER(PARTITION BY metric_id ORDER BY data_time DESC,collected_at DESC,batch_id DESC) AS observation_rank
 FROM (
  SELECT t.metric_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(r.data_json,'$.metric_value')) AS DECIMAL(15,4)) AS metric_value,
   CAST(REPLACE(JSON_UNQUOTE(JSON_EXTRACT(r.data_json,'$.data_time')),'T',' ') AS DATETIME) AS data_time,
   f.collected_at,f.id AS batch_id
  FROM release_collection_targets_20261020 t JOIN collection_file f ON f.source_code=t.source_code
  JOIN collection_row r ON r.batch_id=f.id AND JSON_UNQUOTE(JSON_EXTRACT(r.data_json,'$.metric_code'))=t.metric_code
  WHERE f.id IN ('c31a6003-2e99-51d6-863e-5cb396a242a6','c050f39d-11db-50bb-ae7a-96b1b3c8ca8d','f04be862-3e7c-5a93-86cf-317007511c3e','d7024118-6c59-505a-9e9f-98d653905785','5e1752a2-fa09-51b5-87e4-4183c1ab05ff','01344c4b-d4f6-5afe-8fa7-a9cf2e7e5e90','a85184db-9acf-520e-a40f-ddae1f4816d7','611f3040-8a98-5ecc-8136-4175ce11c2a6','f65826b4-56f0-56ff-bddc-f2d175dab776','9cd1ff55-1aa6-540e-9005-9fc2ae3a36a7')
 ) observations
) v LEFT JOIN metric_monitor_config cfg ON cfg.metric_id=v.metric_id
WHERE v.observation_rank=1
ON DUPLICATE KEY UPDATE
 data_time=IF(metric_realtime.metric_value IS NULL,VALUES(data_time),metric_realtime.data_time),
 is_exceed=IF(metric_realtime.metric_value IS NULL,VALUES(is_exceed),metric_realtime.is_exceed),
 exceed_count=IF(metric_realtime.metric_value IS NULL,VALUES(exceed_count),metric_realtime.exceed_count),
 status=IF(metric_realtime.metric_value IS NULL,VALUES(status),metric_realtime.status),
 update_time=IF(metric_realtime.metric_value IS NULL,VALUES(update_time),metric_realtime.update_time),
 metric_value=IF(metric_realtime.metric_value IS NULL,VALUES(metric_value),metric_realtime.metric_value);

